def turn_scene(title,a,b,degrees):
    from rotation_constructions import rotated
    t=(0,0);p={'T':t,'A':a,'B':b,'A′':rotated(a,t,degrees),'B′':rotated(b,t,degrees)}
    return picture(title,p,[('T','A'),('T','A′'),('T','B'),('T','B′'),('A','B'),('A′','B′')],'T','A',degrees)


